     1→import * as React from 'react';
     2→import { cva, type VariantProps } from 'class-variance-authority';
     3→import { motion } from 'framer-motion';
     4→
     5→import { cn } from '@/lib/utils';
     6→import { fadeInUp, transitions } from '@/lib/animations';
     7→
     8→const headingVariants = cva('font-display font-bold tracking-tight', {
     9→  variants: {
    10→    variant: {
    11→      default: 'text-foreground',
    12→      primary: 'text-primary',
    13→      muted: 'text-muted-foreground',
    14→      // Gradient variants
    15→      gradient: 'bg-gradient-brand bg-clip-text text-transparent',
    16→      'gradient-primary': 'bg-gradient-primary bg-clip-text text-transparent',
    17→      'gradient-teal': 'bg-gradient-teal bg-clip-text text-transparent',
    18→      'gradient-ocean': 'bg-gradient-ocean bg-clip-text text-transparent',
    19→    },
    20→    size: {
    21→      h1: 'text-5xl md:text-6xl lg:text-7xl',
    22→      h2: 'text-4xl md:text-5xl',
    23→      h3: 'text-3xl md:text-4xl',
    24→      h4: 'text-2xl md:text-3xl',
    25→      h5: 'text-xl md:text-2xl',
    26→      h6: 'text-lg md:text-xl',
    27→      // Display sizes for hero sections
    28→      display: 'text-6xl md:text-7xl lg:text-8xl',
    29→      'display-sm': 'text-5xl md:text-6xl lg:text-7xl',
    30→    },
    31→    align: {
    32→      left: 'text-left',
    33→      center: 'text-center',
    34→      right: 'text-right',
    35→    },
    36→    leading: {
    37→      none: 'leading-none',
    38→      tight: 'leading-tight',
    39→      snug: 'leading-snug',
    40→      normal: 'leading-normal',
    41→    },
    42→  },
    43→  defaultVariants: {
    44→    variant: 'default',
    45→    size: 'h2',
    46→    leading: 'tight',
    47→  },
    48→});
    49→
    50→type HeadingLevel = 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6';
    51→
    52→export interface HeadingProps
    53→  extends React.HTMLAttributes<HTMLHeadingElement>,
    54→    VariantProps<typeof headingVariants> {
    55→  /** HTML heading level to render */
    56→  as?: HeadingLevel;
    57→  /** Enable entrance animation */
    58→  animated?: boolean;
    59→  /** Balance text for better line breaks */
    60→  balance?: boolean;
    61→}
    62→
    63→const Heading = React.forwardRef<HTMLHeadingElement, HeadingProps>(
    64→  (
    65→    {
    66→      className,
    67→      variant,
    68→      size,
    69→      align,
    70→      leading,
    71→      as,
    72→      animated = false,
    73→      balance = false,
    74→      children,
    75→      ...props
    76→    },
    77→    ref
    78→  ) => {
    79→    // Determine the HTML element based on size if 'as' is not provided
    80→    const getElementFromSize = (): HeadingLevel => {
    81→      if (size?.startsWith('h')) {
    82→        return size as HeadingLevel;
    83→      }
    84→      if (size?.startsWith('display')) {
    85→        return 'h1';
    86→      }
    87→      return 'h2';
    88→    };
    89→
    90→    const Component = as || getElementFromSize();
    91→
    92→    const baseClassName = cn(
    93→      headingVariants({ variant, size, align, leading }),
    94→      balance && 'text-balance',
    95→      className
    96→    );
    97→
    98→    // Animated version
    99→    if (animated) {
   100→      return (
   101→        <motion.div
   102→          initial="hidden"
   103→          whileInView="visible"
   104→          viewport={{ once: true, margin: '-100px' }}
   105→          variants={fadeInUp}
   106→          transition={transitions.smooth}
   107→        >
   108→          <Component ref={ref} className={baseClassName} {...props}>
   109→            {children}
   110→          </Component>
   111→        </motion.div>
   112→      );
   113→    }
   114→
   115→    return (
   116→      <Component ref={ref} className={baseClassName} {...props}>
   117→        {children}
   118→      </Component>
   119→    );
   120→  }
   121→);
   122→Heading.displayName = 'Heading';
   123→
   124→export { Heading, headingVariants };
   125→

