    65→};
    66→
    67→export const NeoSplitHero: React.FC = () => {
    68→  const t = useTranslations("home.splitHero");
    69→  const tPlayer = useTranslations("musicPlayer");
    70→  const locale = useLocale();
    71→  const isFrench = locale === "fr";
    72→
    73→  const {
    74→    status,
    75→    mediaAllowed,
