    80→    positionMs,
    81→    durationMs,
    82→    volume,
    83→    error,
    84→    actions,
    85→  } = useGlobalAudioPlayer();
    86→
    87→  const [lastNonZeroVolume, setLastNonZeroVolume] = useState(80);
    88→
    89→  useEffect(() => {
    90→    if (volume > 0) setLastNonZeroVolume(volume);
    91→  }, [volume]);
    92→
    93→  const progress = durationMs > 0 ? Math.min(1, positionMs / durationMs) : 0;
    94→  const remainingMs = Math.max(0, durationMs - positionMs);
    95→  const externalUrl = track?.permalinkUrl || SOUND_CLOUD_PROFILE_URL;
    96→  const artworkUrl = normalizeArtworkUrl(track?.artworkUrl ?? null, "t500x500");
    97→
    98→  const { samples, isLoading: isWaveformLoading } = useSoundCloudWaveform(
    99→    mediaAllowed ? track?.waveformUrl : null,
   100→    track?.id,
   101→    96
   102→  );
   103→
   104→  const isPlayerUnavailable = status === "error" || !!error;
   105→  const controlsDisabled = !mediaAllowed || status !== "ready" || isPlayerUnavailable;
   106→
   107→  const statusLabel = useMemo(() => {
   108→    if (!mediaAllowed) return tPlayer("status.mediaDisabled");
   109→    if (isPlayerUnavailable) return tPlayer("status.unavailable");
   110→    if (status === "loading") return tPlayer("status.loading");
   111→    return isPlaying ? tPlayer("status.playing") : tPlayer("status.paused");
   112→  }, [isPlayerUnavailable, isPlaying, mediaAllowed, status, tPlayer]);
