   116→      className="container mx-auto px-4 md:px-6 mb-16 min-h-[calc(100vh-8rem)] flex flex-col lg:grid lg:grid-cols-[60fr_40fr] gap-8 lg:gap-12 items-center"
   117→      variants={containerVariants}
   118→      initial="hidden"
   119→      animate="visible"
   120→    >
   121→      {/* Left Panel - Text Content */}
   122→      <motion.div
   123→        className="flex flex-col justify-center w-full pt-8 md:pt-0"
   124→        variants={leftPanelVariants}
   125→      >
   126→        <div className="font-mono text-xs font-bold text-neo-accent flex items-center gap-2 mb-4">
   127→          <div className="w-2 h-2 bg-neo-accent animate-pulse" />
   128→          {t("basedIn")}
   129→        </div>
   130→
   131→        <h1 className="text-[9vw] sm:text-[10vw] lg:text-[7vw] xl:text-[6vw] leading-[0.9] font-black tracking-tighter uppercase break-words mb-6 text-neo-text max-w-full">
   132→          {t("title.line1")} <br />
   133→          <motion.span
   134→            variants={stampVariants}
   135→            className="inline-block relative px-3 md:px-4 py-1 md:py-2 bg-neo-accent text-neo-text-inverse border-4 border-neo-text shadow-[8px_8px_0px_0px_var(--neo-text)] my-2 whitespace-nowrap origin-center text-center"
   136→            style={{
   137→              fontStretch: "condensed",
   138→              letterSpacing: "-0.03em",
   139→            }}
   140→          >
   141→            {t("title.line2")}
   142→          </motion.span>{" "}
   143→          <br />
   144→          <span className={`inline-block whitespace-nowrap${isFrench ? " mt-1 sm:mt-0" : ""}`}>
   145→            {t("title.line3")}
   146→          </span>
   147→        </h1>
   148→
   149→        <motion.div
   150→          className="max-w-lg"
   151→          initial={{ opacity: 0 }}
   152→          animate={{ opacity: 1 }}
   153→          transition={{ delay: 0.6 }}
   154→        >
   155→          <p className="font-mono text-sm md:text-base font-medium border-l-4 border-neo-accent pl-4 md:pl-6 bg-neo-surface p-4 shadow-[4px_4px_0px_0px_var(--neo-shadow)] text-neo-text">
   156→            {t("tagline")}
   157→          </p>
   158→        </motion.div>
   159→      </motion.div>
   160→
   161→      {/* Right Panel - Persistent SoundCloud Player */}
   162→      <motion.div
   163→        className="w-full lg:sticky lg:top-24 lg:w-[520px] lg:max-w-[520px] lg:justify-self-end"
   164→        variants={rightPanelVariants}
   165→      >
   166→        <div className="relative">
   167→          <div className="absolute -top-2 -left-2 w-full h-full border-4 border-neo-border bg-neo-bg -z-10" />
   168→
   169→          <div
   170→            data-hero-audio-player="true"
   171→            className="border-4 border-neo-border bg-neo-surface shadow-[12px_12px_0px_0px_var(--neo-accent)] overflow-hidden w-full"
   172→          >
   173→            {/* Header */}
   174→            <div className="border-b-4 border-neo-border bg-neo-text text-neo-text-inverse p-4">
   175→              <div className="flex items-center gap-3">
   176→                <div className="w-12 h-12 bg-neo-accent flex items-center justify-center border-2 border-neo-border shadow-[3px_3px_0px_0px_var(--neo-shadow)]">
   177→                  <SoundCloudIcon className="w-6 h-6 text-neo-text-inverse" />
   178→                </div>
   179→                <div className="min-w-0 flex-1">
   180→                  <div className="font-black text-lg uppercase tracking-tight truncate">
   181→                    {t("player.soundcloud")}
   182→                  </div>
   183→                </div>
   184→                <a
